INSERT INTO `wp_options` VALUES (2411,'_transient_novamira_update_info','a:13:{s:4:\"name\";s:8:\"Novamira\";s:7:\"version\";s:7:\"1.12.13\";s:6:\"author\";s:11:\"Dynamic.ooo\";s:15:\"author_homepage\";s:24:\"https://www.dynamic.ooo/\";s:8:\"homepage\";s:19:\"https://novamira.ai\";s:8:\"requires\";s:3:\"6.9\";s:12:\"requires_php\";s:3:\"8.0\";s:6:\"tested\";s:5:\"7.1.3\";s:12:\"last_updated\";s:19:\"2026-10-27 14:29:22\";s:8:\"sections\";a:2:{s:9:\"changelog\";s:631:\"v1.12.13 - 2026/10/27<br />* Fix: On hosting with PHP open_basedir restrictions, looking for WP-CLI no longer prints PHP warnings that broke AI client connections.<br />* Fix: After authorizing or denying a device on the Authorize Device page, the page now shows only the result, instead of also asking for another code.<br />* Fix: On Windows servers, upload links and file abilities now accept absolute paths with a drive letter (such as C:\\...), where uploads previously failed with a directory creation error.<br />* Minor Fixes<br /><br /><br />For full list of changelog <a href=\"https://novamira.ai/changelog\">click here</a>\";s:11:\"description\";s:470:\"Novamira turns your WordPress site into a programmable environment for AI. Your AI client connects to your site directly over the Model Context Protocol and works with real PHP, the database, files, themes, and plugins, the same building blocks you would use yourself. The plugin runs on your own server, so the connection is direct: no proxy, and no data passing through our servers. Your AI, your WordPress. Nothing in between. Built for development and staging sites.\";}s:5:\"icons\";a:2:{s:2:\"1x\";s:60:\"https://license.dynamic.ooo/assets/novamira/icon-128x128.png\";s:2:\"2x\";s:60:\"https://license.dynamic.ooo/assets/novamira/icon-256x256.png\";}s:7:\"banners\";a:2:{s:4:\"high\";s:63:\"https://license.dynamic.ooo/assets/novamira/banner-1544x500.png\";s:3:\"low\";s:62:\"https://license.dynamic.ooo/assets/novamira/banner-772x250.png\";}s:12:\"download_url\";s:88:\"https://nbg1.your-objectstorage.com/ooo-zips-free/novamira/versions/novamira-1.12.13.zip\";}','off');
